21	/**
22	 * The one filter chain: stateless, cross-origin to the frontend, denying what it does not
23	 * name.
24	 *
25	 * <p>This application has no authentication and no principal — design decision 2 declined
26	 * to model a user, and nothing downstream learns who called. That deferral is why the
27	 * chain exists at all: an absent dependency and a deliberate decision are
28	 * indistinguishable in a running application, and only one of them denies an
29	 * unrecognised path. The one real authorization rule arrives with the endpoint it
30	 * protects (design decision 10).
31	 *
32	 * <p>It sits in the root package beside the application class because it belongs to no
33	 * slice; the domain packages own their own behaviour, not the chain in front of it.
34	 *
35	 * <p>See design decision 2 for the alternatives this was chosen over.
36	 */
37	@Configuration
38	@EnableWebSecurity
39	class SecurityConfiguration {
40	
41		private static final String PUBLIC_API = "/api/**";
42	
43		private static final String HEALTH_CHECK = "/actuator/health";
44	
45		private static final String[] API_DOCUMENTATION = {
46				"/v3/api-docs/**", "/swagger-ui/**", "/swagger-ui.html"};
47	
48		/** Named in {@code CONTEXT.md}; ticket 16 gives it a constant in the slice that reads it. */
49		private static final String IDEMPOTENCY_KEY_HEADER = "X-Idempotency-Key";
50	
51		@Bean
52		SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
53			return http
54					// No cookie, no Authorization header, no credentials on a cross-origin call:
55					// a CSRF token would defend ambient authority that does not exist here.
56					.csrf(AbstractHttpConfigurer::disable)
57					// Security runs ahead of MVC and answers the CORS preflight itself, so this
58					// entry is required and a @CrossOrigin annotation would never be reached.
59					.cors(Customizer.withDefaults())
60					// Nothing is remembered between requests, so a session would be state with no
61					// reader — and a cookie the CSRF decision above assumes is absent.
62					.sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
63					.authorizeHttpRequests(request -> request
64							// Authorization runs on the ERROR dispatch too, where denying turns every
65							// 404 and 405 into an empty 403. ASYNC continues a request already
66							// authorized on its way in.
67							.dispatcherTypeMatchers(DispatcherType.ERROR, DispatcherType.ASYNC).permitAll()
68							.requestMatchers(PUBLIC_API).permitAll()
69							.requestMatchers(HEALTH_CHECK).permitAll()
70							.requestMatchers(API_DOCUMENTATION).permitAll()
71							.anyRequest().denyAll())
72					.build();
73		}
74	
75		/**
