77		 * mock FX provider stands in for a third party reached server-to-server, and putting it
78		 * under our CORS policy would undo the isolation it exists for (design decision 28).
79		 *
80		 * @param allowedOrigins the origins allowed to call this API from a browser, defaulting
81		 *                       to the Vite dev server that design decision 20 runs as a
82		 *                       separate process
83		 */
84		@Bean
85		CorsConfigurationSource corsConfigurationSource(
86				@Value("${payments.cors.allowed-origins}") List<String> allowedOrigins) {
87			CorsConfiguration policy = new CorsConfiguration();
88			policy.setAllowedOrigins(allowedOrigins);
89			policy.setAllowedMethods(List.of(HttpMethod.GET.name(), HttpMethod.POST.name()));
90			policy.setAllowedHeaders(List.of(HttpHeaders.CONTENT_TYPE, IDEMPOTENCY_KEY_HEADER));
91			// Only CORS-safelisted response headers reach cross-origin JavaScript, and
92			// Retry-After carries the retry policy of design decision 18.
93			policy.setExposedHeaders(List.of(HttpHeaders.RETRY_AFTER));
