3	import hu.bankmonitor.testsupport.BootedApplicationTest;
4	import hu.bankmonitor.testsupport.ThreadProbeController;
5	import org.junit.jupiter.api.DisplayName;
6	import org.junit.jupiter.api.Nested;
7	import org.junit.jupiter.api.Test;
8	import org.springframework.beans.factory.annotation.Autowired;
9	import org.springframework.context.ApplicationContext;
10	import org.springframework.http.HttpStatus;
11	import org.springframework.security.core.userdetails.UserDetailsService;
12	
13	import static org.assertj.core.api.Assertions.assertThat;
14	
15	/**
16	 * The filter chain of {@link SecurityConfiguration}, asserted through a running server
17	 * rather than by reading the configuration back.
18	 *
19	 * <p>Every test here states an effect a caller can observe — a status code, a response
20	 * header, the absence of a cookie — because the claim design decision 2 makes is that
21	 * "no authentication" was configured rather than skipped, and a test that asserted
22	 * {@code csrf().disable()} was called would only restate the source file.
23	 */
24	class SecurityChainTest extends BootedApplicationTest {
25	
26		/** The Vite dev server of design decision 20, which runs as its own process. */
27		private static final String FRONTEND_DEV_ORIGIN = "http://localhost:5173";
28	
29		private static final String A_PATH_UNDER_THE_PUBLIC_API = ThreadProbeController.PATH;
30	
31		@Autowired
32		private ApplicationContext context;
33	
34		@Test
35		@DisplayName("the public API answers without credentials")
36		void publicApiAnswersWithoutCredentials() {
37			client().get().uri(A_PATH_UNDER_THE_PUBLIC_API)
38					.exchange()
39					.expectStatus().isOk();
40		}
41	
42		/**
43		 * A stateless chain that quietly issued a session cookie would still pass every status
44		 * assertion here, so the cookie is what the policy is measured by.
45		 */
46		@Test
47		@DisplayName("no session cookie is issued")
48		void issuesNoSessionCookie() {
49			client().get().uri(A_PATH_UNDER_THE_PUBLIC_API)
50					.exchange()
51					.expectHeader().doesNotExist("Set-Cookie");
52		}
53	
54		/**
55		 * With CSRF protection on, {@code CsrfFilter} rejects a token-less POST at
56		 * {@code 403} before the request reaches the dispatcher. Reaching the dispatcher — and
57		 * being told the path has no POST handler — is therefore the observable difference.
58		 */
59		@Test
60		@DisplayName("an unsafe method needs no CSRF token")
61		void unsafeMethodNeedsNoCsrfToken() {
62			client().post().uri(A_PATH_UNDER_THE_PUBLIC_API)
63					.exchange()
64					.expectStatus().isEqualTo(HttpStatus.METHOD_NOT_ALLOWED);
65		}
66	
67		/**
68		 * Left alone, Boot auto-configures an in-memory user with a random password and logs it
69		 * at every startup, telling the reader that the security configuration is a placeholder
70		 * still to be replaced. There is no login here to hold an account against.
71		 */
72		@Test
73		@DisplayName("no default user account exists")
74		void hasNoDefaultUserAccount() {
75			assertThat(context.getBeanNamesForType(UserDetailsService.class)).isEmpty();
76		}
77	
78		@Test
79		@DisplayName("a path the chain does not name is denied")
80		void deniesAPathTheChainDoesNotName() {
81			client().get().uri("/not-a-path-the-chain-names")
82					.exchange()
83					.expectStatus().isForbidden();
84		}
85	
86		/**
87		 * The authorization filter runs on the {@code ERROR} dispatch too, so a deny-by-default
88		 * chain that forgets to permit it turns every 404 and 405 under a permitted prefix into
89		 * an empty 403 — and takes ticket 05's problem documents with it.
90		 */
91		@Test
92		@DisplayName("a miss under the public API is a 404, not a denial")
93		void missUnderThePublicApiIsNotFoundRatherThanDenied() {
94			client().get().uri("/api/no-such-endpoint")
95					.exchange()
96					.expectStatus().isNotFound();
97		}
98	
99		@Nested
100		@DisplayName("cross-origin")
101		class CrossOrigin {
102	
103			/**
104			 * Security runs before MVC and answers the preflight itself, so this fails unless
105			 * the chain carries the CORS entry <em>and</em> a {@code CorsConfigurationSource}
106			 * bean exists. A {@code @CrossOrigin} annotation would not be reached.
107			 */
108			@Test
109			@DisplayName("a preflight from the frontend dev origin is answered")
110			void answersPreflightFromTheFrontendDevOrigin() {
111				client().options().uri(A_PATH_UNDER_THE_PUBLIC_API)
112						.header("Origin", FRONTEND_DEV_ORIGIN)
113						.header("Access-Control-Request-Method", "GET")
114						.exchange()
115						.expectStatus().isOk()
116						.expectHeader().valueEquals("Access-Control-Allow-Origin", FRONTEND_DEV_ORIGIN);
117			}
118	
119			@Test
120			@DisplayName("the idempotency key survives the preflight")
121			void allowsTheIdempotencyKeyHeader() {
122				client().options().uri(A_PATH_UNDER_THE_PUBLIC_API)
123						.header("Origin", FRONTEND_DEV_ORIGIN)
124						.header("Access-Control-Request-Method", "POST")
125						.header("Access-Control-Request-Headers", "X-Idempotency-Key")
126						.exchange()
127						.expectStatus().isOk()
128						.expectHeader().valueEquals("Access-Control-Allow-Headers", "X-Idempotency-Key");
129			}
130	
131			/**
132			 * Only the safelisted response headers reach cross-origin JavaScript by default, so
133			 * without this the frontend's retry policy reads {@code Retry-After} as absent —
134			 * a failure that appears in the browser and not in {@code curl}.
135			 */
136			@Test
137			@DisplayName("Retry-After is readable by cross-origin JavaScript")
138			void exposesRetryAfterToTheBrowser() {
139				client().get().uri(A_PATH_UNDER_THE_PUBLIC_API)
140						.header("Origin", FRONTEND_DEV_ORIGIN)
141						.exchange()
142						.expectHeader().valueEquals("Access-Control-Expose-Headers", "Retry-After");
143			}
144	
145			/** An allow-list that accepted anything would pass every test above. */
146			@Test
147			@DisplayName("a preflight from an unlisted origin is refused")
148			void refusesPreflightFromAnUnlistedOrigin() {
149				client().options().uri(A_PATH_UNDER_THE_PUBLIC_API)
150						.header("Origin", "https://not-our-frontend.example")
151						.header("Access-Control-Request-Method", "GET")
152						.exchange()
153						.expectStatus().isForbidden()
154						.expectHeader().doesNotExist("Access-Control-Allow-Origin");
155			}
156	
157			/**
158			 * Credentials off is what keeps CSRF-off safe: no cookie or {@code Authorization}
159			 * header rides along on a cross-origin call, so there is no ambient authority for a
160			 * forged request to borrow.
161			 */
162			@Test
163			@DisplayName("no credentials ride along on a cross-origin call")
164			void allowsNoCredentials() {
165				client().options().uri(A_PATH_UNDER_THE_PUBLIC_API)
166						.header("Origin", FRONTEND_DEV_ORIGIN)
167						.header("Access-Control-Request-Method", "GET")
168						.exchange()
169						.expectHeader().doesNotExist("Access-Control-Allow-Credentials");
170			}
171		}
172	}
