1	package hu.bankmonitor.testsupport;
2	
3	import org.springframework.boot.test.context.SpringBootTest;
4	import org.springframework.boot.test.web.server.LocalServerPort;
5	import org.springframework.context.annotation.Import;
6	import org.springframework.test.web.servlet.client.RestTestClient;
7	
8	/**
9	 * Base for tests that need the whole application running on a real port.
10	 *
11	 * <p>The configuration lives here rather than being repeated on each subclass for a
12	 * reason beyond tidiness: Spring caches one application context per distinct
13	 * configuration, so two classes differing by a single annotation pay two boots. Holding
14	 * the annotations in one place makes the shared context structural rather than a
15	 * coincidence the next edit could break.
16	 *
17	 * <p>{@code RANDOM_PORT} rather than MockMvc, because the claims these tests make are
18	 * about the servlet container itself — that a request reaches a listening socket, and
19	 * what kind of thread Tomcat serves it on. MockMvc would bypass it and prove neither.
20	 */
21	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
22	@Import(ThreadProbeController.class)
23	public abstract class BootedApplicationTest {
24	
25		@LocalServerPort
26		private int port;
27	
28		/**
29		 * A client bound to the running server. {@code TestRestTemplate} is gone in Spring
30		 * Boot 4; {@code RestTestClient} is its Spring Framework 7 replacement.
31		 */
32		protected RestTestClient client() {
33			return RestTestClient.bindToServer().baseUrl("http://localhost:" + port).build();
34		}
35	}
